    out = [row[:] for row in grid]

    for r in range(h):
        zeros = [c for c, v in enumerate(grid[r]) if v == 0]
        markers = [c for c, v in enumerate(grid[r]) if v not in (0, 5)]
        for c in markers:
            color = grid[r][c]
            # The ray extends from the marker toward the opposite edge,
            # with the marker changed to 4.
            out[r][c] = 4
            if zeros:
                z = min(zeros, key=lambda x: abs(x-c))
                direction = 1 if c > z else -1
            else:
                direction = 1
            j = c + direction
            while 0 <= j < w:
                if grid[r][j] == 0:
                    break
                out[r][j] = color
                j += direction

    # Also cast the rays vertically from the aligned zero bars.
    for c in range(w):
        if all(grid[r][c] == 0 for r in range(h)):
            continue
    return out
